using ModConfigEnhance.Overview;
using ModConfigEnhance.Updating;
using Newtonsoft.Json;
int n=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);n++;}
string root=Path.Combine(Path.GetTempPath(),"mce-source-"+Guid.NewGuid());Directory.CreateDirectory(root);
BepInEx.Paths.BepInExRootPath=root;Loc.RootDirectory=Path.Combine(root,"config");Directory.CreateDirectory(Loc.RootDirectory);
string folder=Path.Combine(root,"plugins","Demo");Directory.CreateDirectory(folder);string dll=Path.Combine(folder,"Feature.dll");File.WriteAllText(dll,"fixture");
OverviewMod Mod()=>new(){Guid="feature",Id="feature",PackageName="Demo",RawName="Demo",PackageRoot=folder,Location=dll,PackageVersion="1.0.0"};
ShopCatalog.Items=new(){new(){Team="Team",Name="Demo",Version="1.0.0",Versions=new(){new(){Version="1.0.0"}}}};
string published=Path.Combine(root,"published");Directory.CreateDirectory(published);PublishedPack.Packs.Add(new(){Root=published});
File.WriteAllText(Path.Combine(published,"sources.json"),JsonConvert.SerializeObject(new Dictionary<string,ModSourceRecord>{{"feature",new(){kind=ModSourceKind.Local,ns="Team",name="Demo"}}}));
var m=Mod();ModSources.Apply(m);Check(!ModSources.ExplicitLocal(m)&&m.SourceKind!=ModSourceKind.Local,"legacy published Local not user decision");
ModSources.Set(new[]{m},new(){kind=ModSourceKind.Local});ModSources.Apply(m);Check(ModSources.ExplicitLocal(m)&&m.SourceKind==ModSourceKind.Local,"explicit personal local choice preserved with installation fingerprint");
File.WriteAllText(dll,"fixture updated in-place");ModSources.Apply(m);
Check(ModSources.ExplicitLocal(m)&&m.SourceKind==ModSourceKind.Local,"personal local policy survives in-place DLL/version changes");
var moved=Mod();moved.PackageRoot=Path.Combine(root,"different-package");
Check(!ModSources.ExplicitLocal(moved),"modern local choice does not leak into another package installation");
string personal=Path.Combine(Loc.RootDirectory,"runtime","sources.json");
File.WriteAllText(personal,JsonConvert.SerializeObject(new Dictionary<string,ModSourceRecord>{{"feature",new(){kind=ModSourceKind.Local}}}));ModSources.InvalidateRecords();
m=Mod();ModSources.Apply(m);
Check(ModSources.ExplicitLocal(m)&&m.SourceKind==ModSourceKind.Local,"legacy personal Local without explicitLocal or fingerprint preserved");
await ModSources.Discover(new[]{m},CancellationToken.None,true);
Check(m.SourceKind==ModSourceKind.Local,"batch discovery preserves legacy personal opt-out");
ShopCatalog.Items=new(){new(){Team="Team",Name="DifferentStoreName",Version="1.0.0",Versions=new(){new(){Version="1.0.0"}}}};
ModSources.Confirm(m,new StorePackage{Author="Team",Name="DifferentStoreName"});ModSources.Apply(m);
Check(m.SourceConfirmed&&m.SourceName=="DifferentStoreName","manual selection may intentionally differ from original package name");
File.WriteAllText(dll,"another in-place update");ModSources.Apply(m);
Check(m.SourceConfirmed&&m.SourceName=="DifferentStoreName","manual source survives in-place DLL update");
ModSources.Set(new[]{m},new(){kind=ModSourceKind.Local});
string path=Path.Combine(root,"MCE","shop","installed-unmanaged.json");Directory.CreateDirectory(Path.GetDirectoryName(path)!);
var package=new ShopPackage{Key="Team-Demo",Version="1.0.0",Url="https://thunderstore.io/package/download/Team/Demo/1.0.0/",Files=new(){new(){Path="plugins/Demo/Feature.dll"}}};
void Ledger(){File.WriteAllText(path,JsonConvert.SerializeObject(new ShopLedger{Packages=new(){package}}));File.SetLastWriteTimeUtc(path,DateTime.UtcNow.AddSeconds(n));}
Ledger();ShopCatalog.Items.Clear();ModSources.Apply(m);
Check(m.SourceConfirmed&&m.SourceKind==ModSourceKind.Store&&m.SourceNamespace=="Team","successful store receipt overrides old/local classification without catalog");
Check(!ModSources.ExplicitLocal(m),"store receipt also excludes local badge and retry skip");
await ModSources.Discover(new[]{m},CancellationToken.None,true);Check(m.SourceConfirmed&&m.SourceKind==ModSourceKind.Store,"discovery does not downgrade installed receipt without catalog");
package.External=true;Ledger();m=Mod();ModSources.Apply(m);Check(!m.SourceConfirmed,"external reuse not claimed as downloaded provenance");
package.External=false;package.Files[0].Path="plugins/Other/Feature.dll";Ledger();m=Mod();ModSources.Apply(m);Check(!m.SourceConfirmed,"same GUID or filename without exact receipt path cannot relabel");
package.Files[0].Path="plugins/Demo/Feature.dll";package.Url="https://example.com/package/download/Team/Demo/1.0.0/";Ledger();m=Mod();ModSources.Apply(m);Check(!m.SourceConfirmed,"untrusted download URL not store proof");
package.Url="https://thunderstore.io/package/download/Team/Demo/1.0.0/";Ledger();File.Delete(dll);m=Mod();ModSources.Apply(m);Check(!m.SourceConfirmed,"receipt with removed payload not installed");
File.WriteAllText(dll,"fixture");Ledger();m=Mod();m.SourceKind=ModSourceKind.Local;m.SourceConfirmed=false;
string output=Path.Combine(root,"export");ModSources.Export(output,new[]{m});
var exported=JsonConvert.DeserializeObject<Dictionary<string,ModSourceRecord>>(File.ReadAllText(Path.Combine(output,"sources.json")))![m.Guid];
Check(exported.kind==ModSourceKind.Store&&exported.ns=="Team"&&exported.name=="Demo","export revalidates stale Local row using store receipt");
Check(!exported.explicitLocal&&exported.instance==""&&exported.note==""&&exported.environment=="","export strips personal local policy and fingerprint");
var renamed=Mod();renamed.Author="Team";renamed.AuthorSource="manifest";renamed.PackageName="Demo";
ModSources.ReadManifestIdentity(renamed,Newtonsoft.Json.Linq.JObject.Parse("{\"namespace\":\"Team\",\"name\":\"Demo\",\"FullName\":\"Team-Demo\"}"),"Feature-FriendlyName");
Check(renamed.IdentityConflict=="","renamed descriptive ASCII folder does not conflict with manifest identity");
ModSources.ReadManifestIdentity(renamed,Newtonsoft.Json.Linq.JObject.Parse("{\"namespace\":\"Team\",\"name\":\"Demo\",\"FullName\":\"Team-Demo\"}"),"OtherTeam-Demo");
Check(renamed.IdentityConflict.Length>0,"same package folder declaring another team remains conflict");
var success=Mod();success.Guid="success";success.SourceConfirmed=true;success.SourceKind=ModSourceKind.Store;
var added=Mod();added.Guid="added";added.SourceConfirmed=false;
var pending=Mod();pending.Guid="pending";pending.SourceConfirmed=false;pending.SourceKind=ModSourceKind.Pending;
var local=Mod();local.Guid="local";local.SourceConfirmed=false;local.SourceKind=ModSourceKind.Local;
var batchMods=new[]{success,added,pending,local};var before=SourceIdentificationBatch.CaptureBefore(batchMods);
added.SourceConfirmed=true;added.SourceKind=ModSourceKind.Store;
var batch=new SourceIdentificationBatch(batchMods,before,Array.Empty<StorePackage>(),ModSources.Context);
Check(batch.Identified==2&&batch.NewlyIdentified==1&&batch.Pending==1&&batch.Local==1,"batch includes preexisting success, new success, manual pending and local");
Check(batch.Rows.Count==batch.Identified+batch.Pending+batch.Local,"batch partition conserves all installation rows");
added.SourceConfirmed=false;added.SourceKind=ModSourceKind.Pending;
Check(batch.Identified==2&&batch.NewlyIdentified==1,"frozen batch statistics do not change when live rows refresh");
var repeat=new SourceIdentificationBatch(new[]{success,success,pending},SourceIdentificationBatch.CaptureBefore(new[]{success}),Array.Empty<StorePackage>(),ModSources.Context);
Check(repeat.Rows.Count==2&&repeat.Identified==1&&repeat.NewlyIdentified==0&&repeat.Pending==1,"zero new matches still displays preexisting success; duplicate projection deduplicated");
Check(batch.Summary.Contains("2")&&batch.Summary.Contains("1"),"explicit total/new/pending/local summary produced");
Check(m.SourceKind==ModSourceKind.Local&&!m.SourceConfirmed,"export did not mutate stale input row classification");
var retired=new StorePackage{Author="Retired",Name="OldFeature",Version="1.0.0",Versions=new(){"1.0.0"},Deprecated=true};
Check(new StoreIdentityIndex(new[]{retired}).Identity("Retired","OldFeature")==retired,"deprecated identity remains available for manual source confirmation");
var oldHint=new OverviewMod{Guid="hint-test",PackageRoot=folder,RawName="CurrentFeature",PackageName="CurrentFeature",Author="Team",AuthorSource="manifest"};
File.WriteAllText(Path.Combine(published,"sources.json"),JsonConvert.SerializeObject(new Dictionary<string,ModSourceRecord>{{oldHint.Guid,new(){kind=ModSourceKind.Local,ns="OldTeam",name="RemovedFeature"}}}));
ModSources.InvalidateRecords();
var currentPackage=new StorePackage{Author="Team",Name="CurrentFeature",Version="1.0.0",Versions=new(){"1.0.0"}};
ModSources.Apply(oldHint,new[]{currentPackage});
Check(oldHint.SourceConfirmed&&oldHint.SourceName=="CurrentFeature","stale published hint cannot veto independent current manifest author/name");
var obsolete=new OverviewMod{Guid="obsolete",PackageRoot=folder,RawName="OldFeature",PackageName="OldFeature",Author="Retired",AuthorSource="manifest",SourceNamespace="Retired",SourceName="OldFeature"};
ModSources.Apply(obsolete,new[]{retired});
Check(obsolete.SourceConfirmed&&obsolete.SourceKind==ModSourceKind.Store,"deprecated manifest identity remains identified rather than pending");
var deprecatedBatch=new SourceIdentificationBatch(new[]{obsolete},new(),new[]{retired},ModSources.Context);
Check(deprecatedBatch.Identified==1&&deprecatedBatch.Pending==0&&deprecatedBatch.Rows[0].Deprecated,"deprecated source counted successful with separate availability");
var conflicting=new OverviewMod{Guid=m.Guid,PackageRoot=Path.Combine(root,"other"),RawName="OtherPackage",PackageName="OtherPackage"};
bool rejected=false;try{ModSources.Export(Path.Combine(root,"conflict-export"),new[]{m,conflicting});}catch(InvalidDataException){rejected=true;}
Check(rejected,"same GUID conflicting export identities never silently overwrite");
Directory.Delete(root,true);Console.WriteLine($"PASS {n} production personal-local/store-receipt checks");
namespace ModConfigEnhance.Overview {internal static class OverviewLanguageBridge {internal static string GetDisplayName(OverviewMod m)=>m.Name;}}
namespace BepInEx{internal static class Paths{internal static string BepInExRootPath="";}}
namespace ModConfigEnhance.Updating{public sealed class ShopLedger{public List<ShopPackage> Packages=new();}public sealed class ShopPackage{public string Key="",Version="",Url="";public bool External,VerificationRequired;public List<PackFile> Files=new();}public sealed class PackFile{public string Path="";}}
